function recipeTheory(r){return /\bTEORIA\b/i.test([r.name,r.effect,r.extra].join(' '))}
function statusBadge(r){return recipeTheory(r)?'<span class="badge theory">TEORIA</span>':r.discovered?'<span class="badge">Scoperta</span>':'<span class="badge unknown">Sconosciuta</span>'}
let recipeMode='traditional';
function recipes(){main.innerHTML=`<section class="screen"><h1 class="h">Ricettario delle Opere</h1><div class="mode-switch"><button id="traditional" class="active" type="button">Tradizionali</button><button id="aliumMode" type="button">Alium</button></div><div id="traditionalPanel"><p class="muted">Archivio completo della scheda «Ricette»: opere scoperte e combinazioni da provare. Tutti i dati disponibili sono inclusi offline.</p><input id="q" type="search" placeholder="Cerca nome, effetto, Fonte…"><div class="filters"><select id="rt"><option value="">Tutte le tipologie</option>${[...new Set(RECIPES.map(r=>r.type))].sort().map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="rl"><option value="">Tutti i livelli</option>${[...new Set(RECIPES.map(r=>r.level))].filter(Boolean).map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="rs"><option value="">Tutte le scuole</option>${[...new Set(RECIPES.map(r=>r.school))].filter(Boolean).map(x=>`<option>${esc(x)}</option>`).join('')}</select><select id="rd"><option value="">Scoperte e sconosciute</option><option value="yes">Solo scoperte</option><option value="no">Solo da provare</option><option value="theory">Solo teorie</option></select></div><div id="list"></div></div><div id="aliumPanel" class="hidden"></div></section>`;['q','rt','rl','rs','rd'].forEach(id=>$('#'+id).oninput=filterRecipes);filterRecipes();$('#traditional').onclick=()=>setRecipeMode('traditional');$('#aliumMode').onclick=()=>setRecipeMode('alium');setRecipeMode(recipeMode)}
function setRecipeMode(mode){recipeMode=mode;$('#traditionalPanel').classList.toggle('hidden',mode!=='traditional');$('#aliumPanel').classList.toggle('hidden',mode!=='alium');$('#traditional').classList.toggle('active',mode==='traditional');$('#aliumMode').classList.toggle('active',mode==='alium');if(mode==='alium'){const host=$('#aliumPanel');host.innerHTML=aliumContents();wireAlium()}}
function filterRecipes(){const q=$('#q').value.toLocaleLowerCase('it'),t=$('#rt').value,l=$('#rl').value,s=$('#rs').value,d=$('#rd').value;const rows=RECIPES.filter(r=>(!t||r.type===t)&&(!l||r.level===l)&&(!s||r.school===s)&&(!d||(d==='theory'?recipeTheory(r):d==='yes'?(r.discovered&&!recipeTheory(r)):(!r.discovered&&!recipeTheory(r))))&&(!q||(r.name+' '+r.effect+' '+r.extra+' '+r.parts.join(' ')+' '+r.school).toLocaleLowerCase('it').includes(q)));$('#list').innerHTML=`<p class="counter">${rows.length} combinazioni visualizzate su ${RECIPES.length} · ${RECIPES.filter(x=>x.discovered).length} opere nominate</p>`+rows.map(r=>`<details class="recipe"><summary><div class="line"><span class="name">${esc(r.discovered?r.name:'Combinazione da provare')}</span>${statusBadge(r)}</div><div class="muted">${esc(r.type)} · ${esc(r.level)} · ${esc(r.school||'Scuola non indicata')}</div>${dots(r.parts)}</summary><div class="detail-block"><b>Fonti nell’ordine indicato dal foglio</b><ol class="ingredient-list">${r.parts.map((p,i)=>`<li>${esc(p)}${i===r.parts.length-1?' · Chiusura, Gen. 1':''}</li>`).join('')}</ol><p><b>Effetto:</b> ${esc(r.effect||'Non ancora conosciuto')}</p>${r.extra?`<p><b>Effetto supplementare / note:</b> ${esc(r.extra)}</p>`:''}<p class="muted">Riga ${r.id} del foglio Ricette. La quantità di componenti fisici dipende dal percorso calcolato.</p></div></details>`).join('')}
function opts(selected){return Object.keys(COLORS).map(s=>`<option ${s===selected?'selected':''}>${s}</option>`).join('')}
function resetParts(){const fixed=TYPES[type]||TYPES.POZIONE;parts=Array(size==='BASE'?4:size==='MEDIO'?5:6).fill('Equilibrio');parts[0]=fixed[0];parts[parts.length-1]=fixed[1]}
function calc(){main.innerHTML=`<section class="screen"><h1 class="h">Ruota del Creazionismo</h1><p class="muted">Configura la combinazione. Il riconoscimento confronta le Fonti con le ricette note; la simulazione dei giri è ancora da validare.</p><div class="panel"><div class="filters"><select id="size"><option value="BASE">Base · 4 passaggi</option><option value="MEDIO">Media · 5 passaggi</option><option value="AVANZATO">Avanzata · 6 passaggi</option></select><select id="type">${Object.keys(TYPES).map(s=>`<option value="${s}">${s}</option>`).join('')}</select></div><div id="steps"></div></div><div id="results"></div></section>`;$('#size').value=size;$('#type').value=type;$('#size').onchange=e=>{size=e.target.value;resetParts();steps()};$('#type').onchange=e=>{type=e.target.value;resetParts();steps()};steps()}
function steps(){$('#steps').innerHTML=parts.map((s,i)=>`<div class="step"><label>${i===0?'Apertura':i===parts.length-1?'Chiusura':'Passaggio '+(i+1)}</label><select data-i="${i}" ${i===parts.length-1?'disabled':''}>${opts(s)}</select><span class="dot" style="background:${COLORS[s]}">${SHORT[s]}</span></div>`).join('')+`<p class="muted">La chiusura è fissa: ${parts.at(-1)}, generazione 1. L'apertura è modificabile.</p>`;document.querySelectorAll('#steps select').forEach(el=>el.onchange=e=>{parts[+e.target.dataset.i]=e.target.value;steps()});results()}
// Ruota: trascrizione esatta delle 15 posizioni per generazione dal foglio "Ruota".
const WHEEL_ROWS=[
['—','EQ','—','EN','FO','CA','MA','SP','—','EQ','MA','EN','CA','SP','FO'],
['EN','—','FO','EQ','SP','—','FO','MA','EQ','CA','—','EN','SP','CA','MA'],
['CA','FO','—','MA','EN','—','EQ','SP','EQ','SP','MA','—','CA','FO','EN'],
['MA','—','EN','—','CA','EQ','—','EN','MA','FO','CA','EQ','SP','SP','FO']
];
const GENPATHS={BASE:[[4,3,2,1],[2,3,2,1],[2,1,2,1]],MEDIO:[[1,2,1,2,1],[1,2,3,2,1],[3,2,1,2,1],[3,2,3,2,1],[3,4,3,2,1]],AVANZATO:[[2,1,2,1,2,1],[2,1,2,3,2,1],[2,3,2,1,2,1],[2,3,2,3,2,1],[2,3,4,3,2,1],[4,3,2,1,2,1],[4,3,2,3,2,1],[4,3,4,3,2,1]]};
const PER_STEP={1:3,2:6,3:9,4:12};
function permutations(a){if(a.length<2)return[a];return a.flatMap((x,i)=>permutations(a.filter((_,j)=>j!==i)).map(p=>[x,...p]))}
function scanTo(source,gen,from){const row=WHEEL_ROWS[gen-1];let first=-1,second=-1;
  for(let step=1;step<=30;step++){
    let pos=from===0?((step-1)%15):((from+step-1)%15);
    if(row[pos]===SHORT[source]){if(first<0)first=step;else{second=step;break}}
  }
  if(first<0||second<0)return null;
  return [first,second];
}
function candidate(seq,gens,choices){let pos=0,total=0,works=0,steps=[];
  for(let i=0;i<seq.length;i++){
    const g=gens[i],find=scanTo(seq[i],g,pos);if(!find)return null;
    const w=find[choices[i]-1];if(w<1||w>15)return null;
    pos=(pos+w-1)%15+1;
    const qty=Math.ceil(w/PER_STEP[g]);total+=qty;works+=w;
    steps.push({source:seq[i],gen:g,work:w,qty,arrival:pos,choice:choices[i]});
  }
  return {total,works,steps,gens,seq};
}
function computeTop10(sources,level){const gensList=GENPATHS[level],centers=sources.slice(1,-1),orders=permutations(centers.map((_,i)=>i));
 const best=[];let count=0;
 for(const gens of gensList)for(const order of orders){const seq=[sources[0],...order.map(i=>centers[i]),sources.at(-1)];
   for(let mask=0;mask<(1<<seq.length);mask++){
     const choices=seq.map((_,i)=>((mask>>i)&1)+1),c=candidate(seq,gens,choices);
     if(!c)continue;count++;best.push(c);
   }
 }
 best.sort((a,b)=>a.total-b.total||a.works-b.works||a.gens.join('').localeCompare(b.gens.join('')));
 return {best:best.slice(0,10),count};
}
function results(){
 const recognized=RECIPES.filter(r=>r.discovered&&r.level===size&&r.type===type&&r.parts.length===parts.length&&r.parts[0]===parts[0]&&r.parts.at(-1)===parts.at(-1)&&r.parts.slice(1,-1).slice().sort().join('|')===parts.slice(1,-1).slice().sort().join('|'));
 const theoryMatch=recognized.find(recipeTheory);
 const art=['RUNA','PERGAMENA','GRIMORIO'].includes(type);
 const {best,count}=computeTop10(parts,size);
 const minQty=best.length?best[0].total:null;
 const sameMin=best.filter(x=>x.total===minQty);
 const priced=sameMin.map(c=>({c,p:priceEstimate(c,'buy')})).filter(x=>x.p!==null).sort((a,b)=>a.p.sum-b.p.sum);
 const priceNote=priced.length===sameMin.length&&sameMin.length?`<p class="notice">★ Minimo ingredienti: ${minQty}. ★ Stima acquisto più conveniente tra le 10 soluzioni visualizzate a parità di ingredienti: ${priced[0].p.sum.toLocaleString('it-IT')} (usando il prezzo più basso per ogni Fonte/Generazione). Verificare disponibilità e prezzi.</p>`:`<p class="notice">★ Percorso più efficiente: ${minQty??'—'} ingredienti. ★ Percorso più economico: non ancora determinabile, mancano i prezzi di acquisto per tutte le Fonti/Generazioni necessarie. Il confronto sarà attivo appena i dati saranno completi.</p>`;
 $('#results').innerHTML=`<h2 class="h">Le 10 soluzioni con meno ingredienti</h2><div class="panel"><div class="line"><b>${recognized.length?esc(recognized[0].name):'Opera non identificata'}</b>${theoryMatch?'<span class="badge theory">TEORIA</span>':recognized.length?'<span class="badge">Scoperta</span>':'<span class="badge unknown">Sconosciuta</span>'}</div><p class="muted">${recognized.length?esc(recognized[0].effect):'Nessun effetto noto nel ricettario locale importato.'}</p>${art?'<p class="warning">Artimagia: validità del sistema ancora da verificare.</p>':''}<p class="muted">Le Fonti centrali possono essere riordinate. La chiusura è sempre in generazione 1.</p></div>
 <p class="muted">${count} percorsi calcolabili · ordinati per quantità di ingredienti, poi per numero totale di lavorazioni. Conteggi ricavati dalle tabelle «Ruota» e «Regole» di Brumo; da confrontare con i risultati del foglio originale.</p>
 ${priceNote}${best.length?best.map((c,i)=>`<details class="recipe"><summary><div class="result-heading"><span class="name">${i+1}. Soluzione</span><span class="tag">${c.total} ingredienti · ${c.works} lavorazioni</span></div><div class="muted">Gen. ${c.gens.join(' → ')}</div>${dots(c.seq)}</summary><div class="calc-stats"><div><strong>${c.total}</strong><small>Ingredienti totali</small></div><div><strong>${c.works}</strong><small>Lavorazioni totali</small></div></div><div class="work-list">${c.steps.map((s,j)=>`<div><b>${j+1}. ${esc(s.source)} · Gen. ${s.gen}</b><p>${s.qty} ingredienti · ${s.work} lavorazioni</p><small>Pallino ${s.arrival} · ${s.choice}° occorrenza</small><div class="move-path"><span class="move-origin">${j===0?'▲ Inizio':'● ' + c.steps[j-1].arrival}</span>${Array.from({length:s.work},(_,k)=>`<span class="move-arrow" title="Lavorazione ${k+1}">➜</span>`).join('')}<span class="move-end">● ${s.arrival}</span></div></div>`).join('')}</div><img class="wheel-original" src="assets/ruota-originale.png" alt="Ruota originale del Creazionismo fornita dall'autore"><p class="notice">La ruota mostrata è l'immagine originale. La posizione di arrivo di ogni passaggio è indicata sopra. La sovrapposizione grafica del percorso è prevista in un successivo aggiornamento.</p></details>`).join(''):'<div class="notice">Nessun percorso calcolabile con le regole attuali. Questo non dimostra che l’opera sia impossibile.</div>'}
 <p class="notice">Nota: i calcoli sono una trasposizione delle regole di Brumo, non ancora certificata da un confronto sistematico per tutte le combinazioni. Il riconoscimento delle scoperte utilizza la copia completa del foglio Ricette, aggiornata al momento della generazione di questa versione.</p>`;
}
function aliumContents(){return `<div><h1 class="h">Archivio dell'Alium</h1><p class="muted">Tutte le voci compilate nella scheda «Iulian - Alium», con componenti originali, generazione, effetti e note. Le ricette incomplete restano esplicitamente indicate.</p><input id="aq" type="search" placeholder="Cerca gemma, componente o effetto…"><div class="filters"><select id="ast"><option value="">Tutti gli stati</option><option value="known">Scoperta</option><option value="theory">TEORIA</option><option value="unknown">Sconosciuta / incompleta</option></select><select id="agen"><option value="">Tutte le generazioni</option><option value="1">Gen. 1</option><option value="2">Gen. 2</option><option value="3">Gen. 3</option><option value="4">Gen. 4</option></select></div><div id="alist"></div></div>`}
function wireAlium(){['aq','ast','agen'].forEach(id=>$('#'+id).oninput=filterAlium);filterAlium()}
let ING_BY_NAME=new Map(INGREDIENTS.map(x=>[x.name.toLocaleLowerCase('it'),x]));
function ingredientChip(name){const v=ING_BY_NAME.get(String(name).toLocaleLowerCase('it'));const src=v?.source||'';if(/^alium$/i.test(name))return '<span class="ingredient-chip" style="--source:#d4b6e5"><span class="source-mark">AL</span> Alium · Fonte/Gen. non indicate</span>';return `<span class="ingredient-chip" style="--source:${COLORS[src]||'#657a87'}"><span class="source-mark">${src?SHORT[src]:'??'}</span> ${esc(name)} ${v?.gen?'· G'+v.gen:''}</span>`}
function aliumSourceChips(x){return x.ingredients.map(n=>{if(/^alium$/i.test(n))return `<span class="source-token" style="--source:#d4b6e5" title="Fonte e generazione dell’Alium non specificate nel foglio">AL · G?</span>`;const a=ING_BY_NAME.get(n.toLocaleLowerCase('it'));return a?.source?`<span class="source-token" style="--source:${COLORS[a.source]}">${SHORT[a.source]} ${a.gen?'G'+a.gen:''}</span>`:''}).filter(Boolean).join('')}
function filterAlium(){let q=$('#aq').value.toLocaleLowerCase('it'),st=$('#ast').value,gen=$('#agen').value;let a=ALIUM.filter(x=>{const status=x.theory?'theory':x.complete?'known':'unknown';return (!st||st===status)&&(!gen||String(x.gen)===gen)&&(!q||(x.name+' '+x.effect+' '+x.note+' '+x.ingredients.join(' ')+' '+x.elements.join(' ')).toLocaleLowerCase('it').includes(q))});$('#alist').innerHTML=`<p class="counter">${a.length} voci visualizzate su ${ALIUM.length} · ${ALIUM.filter(x=>x.theory).length} teorie</p>`+a.map(x=>{const status=x.theory?'TEORIA':x.complete?'Scoperta':'Sconosciuta';const cls=x.theory?'theory':x.complete?'':'unknown';return `<details class="recipe"><summary><div class="line"><span class="name">◇ ${esc(x.name||'Combinazione senza nome')}</span><span class="status-cluster">${aliumSourceChips(x)}<span class="badge ${cls}">${status}</span></span></div><div class="muted">${x.gen?'Generazione '+esc(x.gen)+' · ':''}${x.ingredients.length} componenti indicati</div><p class="muted">${esc(x.ingredients.join(' · ')||'Ingredienti non specificati')}</p></summary><div class="detail-block"><b>Ingredienti precisi</b>${x.ingredients.length?`<ol class="ingredient-list">${x.ingredients.map(v=>`<li>${ingredientChip(v)}</li>`).join('')}</ol>`:'<p class="muted">Non indicati nel foglio originale.</p>'}${x.elements.length?`<p><b>Elementi:</b> ${esc(x.elements.join(' · '))}</p>`:''}<p><b>Effetto:</b> ${esc(x.theory?'TEORIA — effetto non confermato':x.effect||'Non indicato')}</p>${x.note?`<p><b>Note:</b> ${esc(x.note)}</p>`:''}${x.useful?`<p><b>Utile?:</b> ${esc(x.useful)}</p>`:''}${!x.complete?'<p class="warning">Scheda incompleta: non sono presenti tutti i componenti o il nome dell’opera.</p>':''}<p class="muted">Riga ${x.id} della scheda Iulian - Alium.</p></div></details>`}).join('')}
function alium(){main.innerHTML=`<section class="screen">${aliumContents()}</section>`;wireAlium()}
function ingredients(){main.innerHTML=`<section class="screen"><h1 class="h">Ingredienti</h1><p class="muted">Ricerca, filtri e ordinamento dell'archivio. I prezzi non ancora compilati sono indicati con —.</p><input id="iq" type="search" placeholder="Cerca ingrediente…"><div class="filters ingredient-filters"><label>Fonte<select id="is"><option value="">Tutte</option>${Object.keys(COLORS).sort((a,b)=>a.localeCompare(b,'it')).map(x=>`<option>${x}</option>`).join('')}</select></label><label>Generazione<select id="ig"><option value="">Tutte</option>${[1,2,3,4].map(x=>`<option value="${x}">Gen. ${x}</option>`).join('')}</select></label><label>Sintonia A.<select id="ia"><option value="">Tutte</option><option value="yes">Sì</option><option value="no">No</option></select></label><label>Ordine<select id="io"><option value="name-asc">Nome A → Z</option><option value="name-desc">Nome Z → A</option><option value="source-asc">Fonte A → Z · Generazione ↑</option><option value="source-desc">Fonte Z → A · Generazione ↓</option><option value="gen-asc">Generazione ↑ · Fonte A → Z</option><option value="gen-desc">Generazione ↓ · Fonte Z → A</option><option value="sell-asc">Vendita · prezzo crescente</option><option value="sell-desc">Vendita · prezzo decrescente</option><option value="buy-asc">Acquisto · prezzo crescente</option><option value="buy-desc">Acquisto · prezzo decrescente</option><option value="bulk-asc">Acquisto Mercante · prezzo crescente</option><option value="bulk-desc">Acquisto Mercante · prezzo decrescente</option></select></label></div><div id="ilist"></div></section>`;['iq','is','ig','ia','io'].forEach(id=>$('#'+id).oninput=filterIngredients);filterIngredients()}
function numericPrice(v){if(v===null||v===undefined||v==='')return null;const n=Number(String(v).replace(',','.'));return Number.isFinite(n)&&n>=0?n:null}
function filterIngredients(){const q=$('#iq').value.toLocaleLowerCase('it'),src=$('#is').value,g=$('#ig').value,a=$('#ia').value,sort=$('#io').value;const filtered=INGREDIENTS.filter(x=>(!q||(x.name+' '+x.source).toLocaleLowerCase('it').includes(q))&&(!src||x.source===src)&&(!g||String(x.gen)===g)&&(!a||(x.alium?'yes':'no')===a));const [field,dir]=sort.split('-');const sign=dir==='desc'?-1:1;const cmp=(x,y)=>String(x||'').localeCompare(String(y||''),'it',{sensitivity:'base'});filtered.sort((x,y)=>{if(['sell','buy','bulk'].includes(field)){const p=numericPrice(x[field]),r=numericPrice(y[field]);if(p===null)return r===null?cmp(x.name,y.name):1;if(r===null)return -1;return sign*(p-r)||cmp(x.name,y.name)}if(field==='source')return sign*(cmp(x.source,y.source)||(Number(x.gen)||99)-(Number(y.gen)||99))||cmp(x.name,y.name);if(field==='gen')return sign*((Number(x.gen)||99)-(Number(y.gen)||99)||cmp(x.source,y.source))||cmp(x.name,y.name);return sign*cmp(x.name,y.name)});$('#ilist').innerHTML=`<p class="counter">${filtered.length} ingredienti su ${INGREDIENTS.length}</p>`+filtered.map(x=>`<details class="recipe"><summary class="line"><span class="name">${esc(x.name)}</span><span class="source-token" style="--source:${COLORS[x.source]||'#82909b'}">${SHORT[x.source]||'??'} · G${x.gen||'?'}</span></summary><div class="detail-block"><p><b>Fonte:</b> ${esc(x.source)} · <b>Generazione:</b> ${x.gen||'Non indicata'}</p><p><b>Sintonia con Alium:</b> ${x.alium?'Sì':'No'}</p><div class="price-grid"><div><small>Vendita</small><strong>${numericPrice(x.sell)??'—'}</strong></div><div><small>Acquisto</small><strong>${numericPrice(x.buy)??'—'}</strong></div><div><small>Acquisto Mercante</small><strong>${numericPrice(x.bulk)??'—'}</strong></div></div></div></details>`).join('')}
function priceEstimate(c,priceField){let sum=0;const chosen=[];for(const st of c.steps){const matches=INGREDIENTS.filter(x=>x.source===st.source&&Number(x.gen)===Number(st.gen)&&numericPrice(x[priceField])!==null).sort((a,b)=>numericPrice(a[priceField])-numericPrice(b[priceField]));if(!matches.length)return null;sum+=numericPrice(matches[0][priceField])*st.qty;chosen.push(matches[0].name)}return {sum,chosen}}
function settings(){main.innerHTML=`<section class="screen"><h1 class="h">Sincronizzazione ed editor</h1><div class="panel"><h3>Archivio locale</h3><p class="muted">Questa versione conserva una copia dei dati nell'app. Per aggiornare automaticamente le ricette dal foglio Google serve un servizio di sincronizzazione autorizzato.</p><p class="notice">Modalità editor non ancora collegata: una password nel codice pubblico di GitHub Pages non proteggerebbe il foglio. Non inserire credenziali in questa pagina. Prepareremo un accesso verificato sul server prima di consentire modifiche.</p><button class="primary" disabled>Modalità editor · in preparazione</button></div></section>`}
function render(){({home,recipes,calc,ingredients,settings}[tab])()}
const SYNC_STORAGE='ricettario-opere-snapshot-v06';
function loadLocalSnapshot(){try{const d=JSON.parse(localStorage.getItem(SYNC_STORAGE)||'null');if(d?.recipes?.length&&d?.alium?.length&&d?.ingredients?.length){RECIPES=d.recipes;ALIUM=d.alium;INGREDIENTS=d.ingredients;ING_BY_NAME=new Map(INGREDIENTS.map(x=>[x.name.toLocaleLowerCase('it'),x]));}}catch(e){}}
async function refreshRemote(){try{const cfg=await fetch('./sync-config.json',{cache:'no-store'}).then(r=>r.ok?r.json():null);if(!cfg?.readOnlyDataUrl)return;const url=new URL(cfg.readOnlyDataUrl,location.href);if(url.protocol!=='https:')return;const resp=await fetch(url.href,{cache:'no-store'});if(!resp.ok)return;const d=await resp.json();if(!Array.isArray(d.recipes)||!Array.isArray(d.alium)||!Array.isArray(d.ingredients)||!d.recipes.length||!d.ingredients.length)return;RECIPES=d.recipes;ALIUM=d.alium;INGREDIENTS=d.ingredients;ING_BY_NAME=new Map(INGREDIENTS.map(x=>[x.name.toLocaleLowerCase('it'),x]));localStorage.setItem(SYNC_STORAGE,JSON.stringify(d));render();}catch(e){/* offline: use cached snapshot */}}
loadLocalSnapshot();resetParts();render();refreshRemote();window.addEventListener('online',refreshRemote);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshRemote()});if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
